package main

import (
	"encoding/json"
	"fmt"
	"net"
	"regexp"
	"strings"
	"time"

	"github.com/valyala/fasthttp"
)

// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

var (
	// Precompile regexes for performance and safety
	titleRegex = regexp.MustCompile(`(?i)<title[^>]*>(.*?)</title>`)
	descRegex  = regexp.MustCompile(`(?i)<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']|<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']`)
)

// safeClient is a package-level reusable client to prevent connection exhaustion.
// It includes strict timeouts, response size limits, and a custom dialer for SSRF protection.
var safeClient = &fasthttp.Client{
	Dial:                safeDial,
	ReadTimeout:         10 * time.Second,
	WriteTimeout:        10 * time.Second,
	MaxIdleConnDuration: 30 * time.Second,
	MaxConnsPerHost:     10,
	MaxResponseBodySize: 1 * 1024 * 1024, // 1MB limit to prevent OOM/DoS
}

// safeDial resolves the hostname and blocks connections to internal/reserved IP addresses.
// This mitigates SSRF attacks, including those exploiting DNS rebinding or malicious redirects.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, err
	}

	ip := net.ParseIP(host)
	var ips []net.IP
	if ip != nil {
		ips = []net.IP{ip}
	} else {
		ips, err = net.LookupIP(host)
		if err != nil {
			return nil, err
		}
	}

	if len(ips) == 0 {
		return nil, fmt.Errorf("no IP addresses found for host %s", host)
	}

	// Strictly block if any resolved IP points to internal/reserved ranges
	for _, resolvedIP := range ips {
		if resolvedIP.IsLoopback() || resolvedIP.IsPrivate() || resolvedIP.IsLinkLocalUnicast() || resolvedIP.IsLinkLocalMulticast() || resolvedIP.IsUnspecified() {
			return nil, fmt.Errorf("access to internal/reserved IP %s is blocked", resolvedIP.String())
		}
	}

	// Dial the first validated public IP directly to prevent TOCTOU DNS rebinding attacks
	return net.Dial("tcp", net.JoinHostPort(ips[0].String(), port))
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")
	freq.Header.Set("Accept", "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8")

	// Limit redirects to prevent infinite loops. SSRF is still blocked via safeDial on each hop.
	maxRedirectCounts := 5
	if err := safeClient.DoRedirects(freq, res, maxRedirectCounts); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		ctx.Error(fmt.Sprintf("Unexpected status code: %d", res.StatusCode()), fasthttp.StatusBadGateway)
		return
	}

	// Validate Content-Type to ensure we only parse HTML and avoid processing binary/large non-HTML payloads
	contentType := string(res.Header.ContentType())
	if !strings.HasPrefix(strings.ToLower(contentType), "text/html") {
		ctx.Error("Response is not HTML", fasthttp.StatusBadGateway)
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	title, description, err := parseHTMLPreview(bodyBytes)
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML body.
func parseHTMLPreview(body []byte) (title, description string, err error) {
	if matches := titleRegex.FindSubmatch(body); len(matches) > 1 {
		title = strings.TrimSpace(string(matches[1]))
	}
	if matches := descRegex.FindSubmatch(body); len(matches) > 1 {
		// Group 1 matches content when name comes first, Group 2 when content comes first
		desc := matches[1]
		if len(desc) == 0 {
			desc = matches[2]
		}
		description = strings.TrimSpace(string(desc))
	}
	return title, description, nil
}

