// FetchURLPreview handles POST requests to fetch and parse URL metadata
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	var req previewRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil || req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"invalid or missing url field"}`)
		return
	}

	fastReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(fastReq)
	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod("GET")

	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(fastResp)

	// Fetch URL following redirects (max 5)
	if err := httpClient.DoRedirects(fastReq, fastResp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error":"failed to fetch url"}`)
		return
	}

	if fastResp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error":"non-200 status code"}`)
		return
	}

	title, description := parseHTML(fastResp.Body())

	resp := previewResponse{
		Title:       title,
		Description: description,
	}
	respBytes, _ := json.Marshal(resp)

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(respBytes)
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(body []byte) (title, description string) {
	z := html.NewTokenizer(bytes.NewReader(body))
	inTitle := false

	for {
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tn, hasAttr := z.TagName()
			tnStr := strings.ToLower(string(tn))

			if tnStr == "title" {
				inTitle = true
				continue
			}

			if tnStr == "meta" && hasAttr {
				var isDesc bool
				var content string
				for {
					key, val, more := z.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" && strings.ToLower(v) == "description" {
						isDesc = true
					}
					if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if isDesc && content != "" {
					description = strings.TrimSpace(content)
				}
			}
		} else if tt == html.TextToken && inTitle {
			title = strings.TrimSpace(string(z.Text()))
			inTitle = false
		}
	}
	return title, description
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

