package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// urlRequest represents the expected JSON payload
type urlRequest struct {
	URL string `json:"url"`
}

// previewResponse represents the JSON response payload
type previewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// Global HTTP client configured per requirements
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// FetchURLPreview handles POST requests, fetches the URL, parses HTML, and returns metadata
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req urlRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.Error("Invalid JSON payload", fasthttp.StatusBadRequest)
		return
	}

	if strings.TrimSpace(req.URL) == "" {
		ctx.Error("URL field is required", fasthttp.StatusBadRequest)
		return
	}

	// Acquire fasthttp request/response objects from pool
	fastReq := fasthttp.AcquireRequest()
	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(fastReq)
	defer fasthttp.ReleaseResponse(fastResp)

	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod("GET")
	fastReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; GoURLPreview/1.0)")

	// Fetch URL with redirect support as strictly required
	if err := httpClient.DoRedirects(fastReq, fastResp, 10); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	if fastResp.StatusCode() != fasthttp.StatusOK {
		ctx.Error(fmt.Sprintf("Remote server returned status: %d", fastResp.StatusCode()), fasthttp.StatusBadGateway)
		return
	}

	// Extract title and meta description from HTML body
	title, description := extractTitleAndDescription(fastResp.Body())

	// Prepare and send JSON response
	resp := previewResponse{
		Title:       title,
		Description: description,
	}

	jsonBytes, err := json.Marshal(resp)
	if err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonBytes)
}

// extractTitleAndDescription parses HTML bytes to find <title> and <meta name="description">
func extractTitleAndDescription(body []byte) (string, string) {
	var title, description string
	foundTitle := false
	foundDesc := false

	z := html.NewTokenizer(bytes.NewReader(body))
	for {
		if foundTitle && foundDesc {
			break
		}
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tn, _ := z.TagName()
			tag := strings.ToLower(string(tn))

			if tag == "title" && !foundTitle {
				if z.Next() == html.TextToken {
					title = strings.TrimSpace(string(z.Text()))
					foundTitle = true
				}
			} else if tag == "meta" && !foundDesc {
				var isDesc bool
				var content string
				// Iterate over all attributes of the meta tag
				for {
					key, val, more := z.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" && strings.ToLower(v) == "description" {
						isDesc = true
					}
					if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if isDesc {
					description = strings.TrimSpace(content)
					foundDesc = true
				}
			}
		}
	}
	return title, description
}

func main() {
	addr := ":8080"
	log.Printf("Starting URL Preview server on %s\n", addr)
	if err := fasthttp.ListenAndServe(addr, FetchURLPreview); err != nil {
		log.Fatalf("Server error: %v", err)
	}
}

