// safeDial resolves the hostname, validates the IP to prevent SSRF,
// and dials the resolved IP directly to mitigate DNS rebinding attacks.
func safeDial(addr string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(addr)
	if err != nil {
		return nil, fmt.Errorf("invalid address: %w", err)
	}

	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed: %w", err)
	}

	var validIP net.IP
	for _, ip := range ips {
		// Block loopback, private, link-local, and unspecified addresses
		if !ip.IsLoopback() && !ip.IsPrivate() && !ip.IsLinkLocalUnicast() &&
			!ip.IsLinkLocalMulticast() && !ip.IsUnspecified() {
			validIP = ip
			break
		}
	}

	if validIP == nil {
		return nil, fmt.Errorf("access to internal or private IP addresses is not allowed")
	}

	// Dial the resolved IP directly with a timeout to prevent DNS rebinding
	return net.DialTimeout("tcp", net.JoinHostPort(validIP.String(), port), 5*time.Second)
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(body []byte) (title, description string, err error) {
	lowerBody := bytes.ToLower(body)

	// Extract title
	titleStart := bytes.Index(lowerBody, []byte("<title>"))
	if titleStart != -1 {
		titleEnd := bytes.Index(lowerBody[titleStart:], []byte("</title>"))
		if titleEnd != -1 {
			title = strings.TrimSpace(string(body[titleStart+7 : titleStart+titleEnd]))
		}
	}

	// Extract meta description (handles both attribute orders)
	reDesc := regexp.MustCompile(`(?i)<meta\s+(?:name=["']description["']\s+content=["']([^"']+)["']|content=["']([^"']+)["']\s+name=["']description["'])`)
	if matches := reDesc.FindSubmatch(body); len(matches) > 1 {
		if len(matches[1]) > 0 {
			description = strings.TrimSpace(string(matches[1]))
		} else if len(matches[2]) > 0 {
			description = strings.TrimSpace(string(matches[2]))
		}
	}

	return title, description, nil
}

