func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	var req urlRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil || req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"invalid or missing url"}`)
		return
	}

	fastReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(fastReq)
	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod(fasthttp.MethodGet)

	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(fastResp)

	if err := httpClient.DoRedirects(fastReq, fastResp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(fmt.Sprintf(`{"error":"fetch failed: %s"}`, err.Error()))
		return
	}

	if fastResp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(fmt.Sprintf(`{"error":"unexpected status: %d"}`, fastResp.StatusCode()))
		return
	}

	title, desc := parseHTML(fastResp.Body())

	preview := urlPreview{
		Title:       strings.TrimSpace(title),
		Description: strings.TrimSpace(desc),
	}

	data, _ := json.Marshal(preview)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(data)
}

func parseHTML(body []byte) (string, string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var title, desc string
	var walker func(*html.Node)
	walker = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") {
						name = attr.Val
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if strings.EqualFold(name, "description") {
					desc = content
				}
			}
		}
		if title != "" && desc != "" {
			return
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walker(c)
			if title != "" && desc != "" {
				return
			}
		}
	}
	walker(doc)
	return title, desc
}

func extractText(n *html.Node) string {
	var buf strings.Builder
	var f func(*html.Node)
	f = func(node *html.Node) {
		if node.Type == html.TextNode {
			buf.WriteString(node.Data)
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return buf.String()
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

