package main

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"github.com/valyala/fasthttp"
)

type URLRequest struct {
	URL string `json:"url"`
}

type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

var (
	titleRegex    = regexp.MustCompile(`(?i)<title[^>]*>(.*?)</title>`)
	metaDescRegex = regexp.MustCompile(`(?i)<meta[^>]+?(?:name\s*=\s*["']description["'][^>]+?content\s*=\s*["']([^"']*)["']|content\s*=\s*["']([^"']*)["'][^>]+?name\s*=\s*["']description["'])`)
)

func parseHTML(body []byte) (string, string) {
	bodyStr := string(body)
	title := ""
	if matches := titleRegex.FindStringSubmatch(bodyStr); len(matches) > 1 {
		title = strings.TrimSpace(matches[1])
	}

	desc := ""
	if matches := metaDescRegex.FindStringSubmatch(bodyStr); len(matches) > 1 {
		if matches[1] != "" {
			desc = strings.TrimSpace(matches[1])
		} else if matches[2] != "" {
			desc = strings.TrimSpace(matches[2])
		}
	}
	return title, desc
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	if reqBody.URL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")

	if err := client.DoRedirects(req, resp, 5); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	title, description := parseHTML(resp.Body())

	preview := URLPreview{
		Title:       title,
		Description: description,
	}

	respJSON, err := json.Marshal(preview)
	if err != nil {
		ctx.Error("Failed to marshal response", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(respJSON)
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

