// safeDial resolves the hostname and blocks requests to internal/private IPs (SSRF protection).
// It is called for every connection, including redirects, preventing redirect-based SSRF bypasses.
func safeDial(addr string) (net.Conn, error) {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		host = addr
	}

	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed: %w", err)
	}

	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsUnspecified() {
			return nil, fmt.Errorf("SSRF protection: access to internal IP %s is denied", ip.String())
		}
	}

	dialer := &net.Dialer{Timeout: 5 * time.Second}
	return dialer.Dial("tcp", addr)
}

