func isPrivateIP(ip net.IP) bool {
	// Normalize IPv4-mapped IPv6 addresses to IPv4 for consistent checking
	if ip4 := ip.To4(); ip4 != nil {
		ip = ip4
	}
	for _, block := range privateIPBlocks {
		if block.Contains(ip) {
