		}
	}
	return false
}

// safeDial resolves the address and blocks connections to private/reserved IPs.
// This mitigates SSRF attacks, including those attempted via DNS rebinding or redirects.
func safeDial(addr string) (net.Conn, error) {
	tcpAddr, err := net.ResolveTCPAddr("tcp", addr)
	if err != nil {
		return nil, fmt.Errorf("failed to resolve address: %w", err)
	}
	if isPrivateIP(tcpAddr.IP) {
		return nil, fmt.Errorf("access to internal or reserved IP addresses is not allowed")
	}
	return net.DialTCP("tcp", nil, tcpAddr)
}

