package main

import (
	"bytes"
	"encoding/json"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLRequest represents the incoming JSON payload
type URLRequest struct {
	URL string `json:"url"`
}

// URLPreviewResponse represents the outgoing JSON payload
type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// httpClient is configured with DualStack dialing as required
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(body []byte) (string, string) {
	var title, description string
	z := html.NewTokenizer(bytes.NewReader(body))
	foundTitle := false
	foundDesc := false

	for {
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tn, hasAttr := z.TagName()
			tagName := strings.ToLower(string(tn))

			if tagName == "title" && !foundTitle {
				if z.Next() == html.TextToken {
					title = strings.TrimSpace(string(z.Text()))
					foundTitle = true
				}
			} else if tagName == "meta" && hasAttr && !foundDesc {
				var name, content string
				for {
					key, val, more := z.TagAttr()
					k := strings.ToLower(string(key))
					v := string(val)
					if k == "name" && strings.ToLower(v) == "description" {
						name = v
					} else if k == "content" {
						content = v
					}
					if !more {
						break
					}
				}
				if name != "" && content != "" {
					description = strings.TrimSpace(content)
					foundDesc = true
				}
			}
		}

		if foundTitle && foundDesc {
			break
		}
	}

	return title, description
}

// FetchURLPreview handles POST requests, fetches the URL, parses HTML, and returns JSON
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"invalid json body"}`)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"url field is required"}`)
		return
	}

	reqFasthttp := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(reqFasthttp)
	reqFasthttp.SetRequestURI(req.URL)
	reqFasthttp.Header.SetMethod("GET")

	respFasthttp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(respFasthttp)

	// MUST use DoRedirects as per requirements
	if err := httpClient.DoRedirects(reqFasthttp, respFasthttp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"failed to fetch url"}`)
		return
	}

	if respFasthttp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"unexpected status code"}`)
		return
	}

	title, description := parseHTML(respFasthttp.Body())

	res := URLPreviewResponse{
		Title:       title,
		Description: description,
	}

	resBytes, err := json.Marshal(res)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"failed to marshal response"}`)
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetBody(resBytes)
}

func main() {
	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

