// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return "", "", err
	}
	htmlStr := string(data)

	// Extract title
	titleRe := regexp.MustCompile(`(?i)<title[^>]*>\s*(.*?)\s*</title>`)
	if m := titleRe.FindStringSubmatch(htmlStr); len(m) > 1 {
		title = strings.TrimSpace(m[1])
	}

	// Extract meta description (handles both attribute orders)
	descRe := regexp.MustCompile(`(?i)<meta\s+[^>]*name=["']description["'][^>]*content=["']([^"']*)["'][^>]*>|<meta\s+[^>]*content=["']([^"']*)["'][^>]*name=["']description["'][^>]*>`)
	if m := descRe.FindStringSubmatch(htmlStr); len(m) > 1 {
		description = strings.TrimSpace(m[1])
		if description == "" && len(m) > 2 {
			description = strings.TrimSpace(m[2])
		}
	}

	return title, description, nil
}

