package main

import (
	"encoding/json"
	"fmt"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

type URLRequest struct {
	URL string `json:"url"`
}

type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

type ErrorResponse struct {
	Error string `json:"error"`
}

var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		sendJSONError(ctx, fasthttp.StatusMethodNotAllowed, "method not allowed")
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "invalid json payload")
		return
	}

	if strings.TrimSpace(reqBody.URL) == "" {
		sendJSONError(ctx, fasthttp.StatusBadRequest, "url field is required")
		return
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		sendJSONError(ctx, fasthttp.StatusBadGateway, fmt.Sprintf("failed to fetch url: %v", err))
		return
	}

	if resp.StatusCode() != fasthttp.StatusOK {
		sendJSONError(ctx, fasthttp.StatusBadGateway, fmt.Sprintf("unexpected status code: %d", resp.StatusCode()))
		return
	}

	title, description := parseHTML(resp.Body())

	preview := URLPreview{
		Title:       strings.TrimSpace(title),
		Description: strings.TrimSpace(description),
	}

	data, err := json.Marshal(preview)
	if err != nil {
		sendJSONError(ctx, fasthttp.StatusInternalServerError, "failed to encode response")
		return
	}

	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(data)
}

func sendJSONError(ctx *fasthttp.RequestCtx, statusCode int, message string) {
	errResp := ErrorResponse{Error: message}
	data, _ := json.Marshal(errResp)
	ctx.SetContentType("application/json")
	ctx.SetStatusCode(statusCode)
	ctx.SetBody(data)
}

func parseHTML(body []byte) (string, string) {
	doc, err := html.Parse(strings.NewReader(string(body)))
	if err != nil {
		return "", ""
	}

	var title, description string
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				title = extractText(n)
			}
			if n.Data == "meta" {
				var isDesc bool
				var content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") && strings.EqualFold(attr.Val, "description") {
						isDesc = true
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if isDesc {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)
	return title, description
}

func extractText(n *html.Node) string {
	var buf strings.Builder
	var f func(*html.Node)
	f = func(node *html.Node) {
		if node.Type == html.TextNode {
			buf.WriteString(node.Data)
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return buf.String()
}

func main() {
	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

