		return
	}

	// 6. Response Size Validation (Prevent Memory Exhaustion/DoS)
	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}
	if len(bodyBytes) > maxResponseBodySize {
		ctx.Error("Response body too large", fasthttp.StatusBadGateway)
		return
	}

	// 7. Parse HTML
	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	// 8. Return JSON Response
	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
	}
}

// parseHTMLPreview extracts title and meta description from HTML.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return "", "", fmt.Errorf("failed to read HTML: %w", err)
	}

	htmlStr := string(data)

	if m := titleRegex.FindStringSubmatch(htmlStr); len(m) > 1 {
		title = strings.TrimSpace(html.UnescapeString(m[1]))
	}

	if m := descRegex.FindStringSubmatch(htmlStr); len(m) > 1 {
		description = strings.TrimSpace(html.UnescapeString(m[1]))
	}

	return title, description, nil
}

