	}
	if m := descRe1.FindSubmatch(body); len(m) > 1 {
		desc = strings.TrimSpace(html.UnescapeString(string(m[1])))
	} else if m := descRe2.FindSubmatch(body); len(m) > 1 {
		desc = strings.TrimSpace(html.UnescapeString(string(m[1])))
	}
	return title, desc
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		sendJSON(ctx, fasthttp.StatusMethodNotAllowed, errorResponse{Error: "method not allowed"})
		return
	}

	var req urlRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil || req.URL == "" {
		sendJSON(ctx, fasthttp.StatusBadRequest, errorResponse{Error: "invalid request body or missing url"})
		return
	}

	fastReq := fasthttp.AcquireRequest()
	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(fastReq)
	defer fasthttp.ReleaseResponse(fastResp)

	fastReq.SetRequestURI(req.URL)
