package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// HTTP client configured with DualStack dialer as required
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// PreviewResponse represents the JSON response structure
type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// parseHTML extracts the title and meta description from HTML content
func parseHTML(body []byte) (title, description string) {
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode {
			switch n.Data {
			case "title":
				if n.FirstChild != nil {
					title = strings.TrimSpace(n.FirstChild.Data)
				}
			case "meta":
				isDesc := false
				content := ""
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") && strings.EqualFold(attr.Val, "description") {
						isDesc = true
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if isDesc {
					description = strings.TrimSpace(content)
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(doc)
	return title, description
}

// FetchURLPreview handles POST requests, fetches the URL, parses HTML, and returns JSON
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	var reqBody struct {
		URL string `json:"url"`
	}

	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil || reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid or missing url"}`))
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod("GET")

	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Fetch URL following redirects as required
	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"failed to fetch url: %s"}`, err.Error())))
		return
	}

	if resp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(fmt.Sprintf(`{"error":"unexpected status code: %d"}`, resp.StatusCode())))
		return
	}

	title, desc := parseHTML(resp.Body())

	result := PreviewResponse{
		Title:       title,
		Description: desc,
	}

	respJSON, _ := json.Marshal(result)
	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(respJSON)
}

func main() {
	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

