	ReadTimeout:  3 * time.Second,
	WriteTimeout: 3 * time.Second,
}

type urlRequest struct {
	URL string `json:"url"`
}

type previewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		return
	}

	var req urlRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil || req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"invalid or missing url"}`)
		return
	}

	fastReq := fasthttp.AcquireRequest()
	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(fastReq)
	defer fasthttp.ReleaseResponse(fastResp)

	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod("GET")

	if err := fetchClient.DoRedirects(fastReq, fastResp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		ctx.SetBodyString(`{"error":"failed to fetch url"}`)
		return
	}

	title, desc := parseHTML(fastResp.Body())

	resp := previewResponse{
		Title:       title,
		Description: desc,
	}

	data, _ := json.Marshal(resp)
	ctx.SetContentType("application/json")
	ctx.SetBody(data)
}

func parseHTML(body []byte) (string, string) {
	var title, description string
	tokenizer := html.NewTokenizer(bytes.NewReader(body))
	inTitle := false

	for {
		tt := tokenizer.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tn, _ := tokenizer.TagName()
			tag := string(tn)

			if strings.EqualFold(tag, "title") {
				inTitle = true
			} else if strings.EqualFold(tag, "meta") {
				var isDesc bool
				var content string
				for {
					key, val, moreAttr := tokenizer.TagAttr()
					k := string(key)
					v := string(val)
					if strings.EqualFold(k, "name") && strings.EqualFold(v, "description") {
