					}
					if strings.EqualFold(k, "content") {
						content = v
					}
					if !moreAttr {
						break
					}
				}
				if isDesc && content != "" {
					description = content
				}
			}
		} else if tt == html.TextToken {
			if inTitle {
				title = strings.TrimSpace(string(tokenizer.Text()))
			}
		} else if tt == html.EndTagToken {
			tn, _ := tokenizer.TagName()
			if strings.EqualFold(string(tn), "title") {
				inTitle = false
			}
		}
	}
	return title, description
}

func main() {
	fasthttp.ListenAndServe(":8080", FetchURLPreview)
}

