package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLRequest represents the expected JSON payload
type URLRequest struct {
	URL string `json:"url"`
}

// URLPreview represents the successful response payload
type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// ErrorResponse represents an error response payload
type ErrorResponse struct {
	Error string `json:"error"`
}

// Global fasthttp client configured as required
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

// FetchURLPreview handles POST requests, fetches the URL, parses HTML, and returns title/description
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		resp, _ := json.Marshal(ErrorResponse{Error: "invalid JSON body"})
		ctx.SetBody(resp)
		return
	}

	if reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		resp, _ := json.Marshal(ErrorResponse{Error: "url field is required"})
		ctx.SetBody(resp)
		return
	}

	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)
	req.SetRequestURI(reqBody.URL)

	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Use DoRedirects as explicitly required
	if err := httpClient.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		errResp, _ := json.Marshal(ErrorResponse{Error: fmt.Sprintf("failed to fetch URL: %v", err)})
		ctx.SetBody(errResp)
		return
	}

	if resp.StatusCode() != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		errResp, _ := json.Marshal(ErrorResponse{Error: fmt.Sprintf("unexpected status code: %d", resp.StatusCode())})
		ctx.SetBody(errResp)
		return
	}

	title, description := parseHTML(resp.Body())

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	result, _ := json.Marshal(URLPreview{Title: title, Description: description})
	ctx.SetBody(result)
}

// parseHTML extracts the <title> and <meta name="description" content="..."> from HTML bytes
func parseHTML(body []byte) (string, string) {
	var title, description string
	doc, err := html.Parse(bytes.NewReader(body))
	if err != nil {
		return "", ""
	}

	var traverse func(*html.Node)
	traverse = func(n *html.Node) {
		if n.Type == html.ElementNode {
			// Extract title
			if n.Data == "title" && n.FirstChild != nil {
				title = strings.TrimSpace(n.FirstChild.Data)
			}
			// Extract meta description
			if n.Data == "meta" {
				var isDesc bool
				var content string
				for _, attr := range n.Attr {
					if strings.EqualFold(attr.Key, "name") && strings.EqualFold(attr.Val, "description") {
						isDesc = true
					}
					if strings.EqualFold(attr.Key, "content") {
						content = attr.Val
					}
				}
				if isDesc {
					description = strings.TrimSpace(content)
				}
			}
		}
		// Recursively traverse child nodes
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			traverse(c)
		}
	}
	traverse(doc)
	return title, description
}

func main() {
	fmt.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		fmt.Printf("Server error: %v\n", err)
	}
}

