// PreviewResponse represents the JSON response structure.
type PreviewResponse struct {
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Error       string `json:"error,omitempty"`
}

var (
	// Reuse client globally to prevent connection leaks, goroutine exhaustion, and improve performance.
	previewClient = &fasthttp.Client{
		Dial:                safeDial,
		ReadTimeout:         10 * time.Second,
		WriteTimeout:        10 * time.Second,
		MaxIdleConnDuration: 10 * time.Second,
		MaxConnsPerHost:     10,
		MaxResponseBodySize: 2 * 1024 * 1024, // Limit to 2MB to prevent memory exhaustion DoS
	}

	// Precompile regexes for safe and efficient HTML extraction
	titleRegex       = regexp.MustCompile(`(?i)<title[^>]*>\s*(.*?)\s*</title>`)
	descriptionRegex = regexp.MustCompile(`(?i)<meta\s+[^>]*name=["']description["'][^>]*content=["']([^"']*)["']`)
)

// safeDial resolves the target address and blocks connections to restricted IPs.
// This mitigates SSRF attacks, including DNS rebinding, by validating the IP before dialing.
func safeDial(addr string) (net.Conn, error) {
	tcpAddr, err := net.ResolveTCPAddr("tcp", addr)
	if err != nil {
		return nil, err
	}
	if isRestrictedIP(tcpAddr.IP) {
		return nil, fmt.Errorf("access to restricted IP addresses is not allowed")
	}
	return net.DialTCP("tcp", nil, tcpAddr)
}

// isRestrictedIP checks if an IP belongs to loopback, private, link-local, or unspecified ranges.
func isRestrictedIP(ip net.IP) bool {
	return ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified()
}

// FetchURLPreview handles POST requests to fetch URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// 1. Method Validation
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	// 2. Input Parsing & Validation
	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	targetURL := strings.TrimSpace(req.URL)
	if targetURL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	parsedURL, err := url.ParseRequestURI(targetURL)
	if err != nil {
		ctx.Error("Invalid URL format", fasthttp.StatusBadRequest)
		return
	}

	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		ctx.Error("URL must use http or https scheme", fasthttp.StatusBadRequest)
		return
	}

	// 3. Safe HTTP Request Execution
	freq := fasthttp.AcquireRequest()
	res := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(freq)
	defer fasthttp.ReleaseResponse(res)

	freq.SetRequestURI(targetURL)
	freq.Header.SetMethod("GET")
	freq.Header.Set("User-Agent", "URLPreviewBot/1.0")

	// Limit redirects to prevent abuse and infinite loops
	maxRedirectCounts := 5
	if err := previewClient.DoRedirects(freq, res, maxRedirectCounts); err != nil {
		ctx.Error(fmt.Sprintf("Failed to fetch URL: %v", err), fasthttp.StatusBadGateway)
		return
	}

	if res.StatusCode() != fasthttp.StatusOK {
		ctx.Error(fmt.Sprintf("Unexpected status code: %d", res.StatusCode()), fasthttp.StatusBadGateway)
		return
	}

	// 4. Content-Type Validation (Prevents parsing binary/non-HTML payloads)
	contentType := string(res.Header.ContentType())
	if !strings.Contains(contentType, "text/html") {
		ctx.Error("URL does not point to an HTML page", fasthttp.StatusBadGateway)
		return
	}

	bodyBytes := res.Body()
	if len(bodyBytes) == 0 {
		ctx.Error("Empty response body", fasthttp.StatusBadGateway)
		return
	}

	// 5. HTML Parsing
	title, description, err := parseHTMLPreview(bytes.NewReader(bodyBytes))
	if err != nil {
		ctx.Error(fmt.Sprintf("Failed to parse HTML: %v", err), fasthttp.StatusInternalServerError)
		return
	}

	// 6. Response Encoding
	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json; charset=utf-8")
	if err := json.NewEncoder(ctx).Encode(resp); err != nil {
		ctx.Error("Failed to encode response", fasthttp.StatusInternalServerError)
		return
	}
}

// parseHTMLPreview extracts title and meta description from HTML safely.
func parseHTMLPreview(r io.Reader) (title, description string, err error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return "", "", err
	}

	if m := titleRegex.FindSubmatch(data); len(m) > 1 {
		title = strings.TrimSpace(string(m[1]))
	}
	if m := descriptionRegex.FindSubmatch(data); len(m) > 1 {
		description = strings.TrimSpace(string(m[1]))
	}

	return title, description, nil
}

