var metaRe = regexp.MustCompile(`(?i)<meta\s+([^>]+)>`)
var contentRe = regexp.MustCompile(`(?i)content\s*=\s*["']([^"']*)["']`)

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString(`{"error":"method not allowed"}`)
		return
	}

	var reqPayload struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &reqPayload); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"invalid json"}`)
		return
	}

	if reqPayload.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"url field is required"}`)
		return
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqPayload.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(fmt.Sprintf(`{"error":"failed to fetch url: %s"}`, err.Error()))
		return
	}

	body := string(resp.Body())
	title := extractTitle(body)
	description := extractDescription(body)

	result := map[string]string{
		"title":       title,
		"description": description,
	}

	jsonData, _ := json.Marshal(result)
	ctx.SetContentType("application/json")
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(jsonData)
}

func extractTitle(htmlStr string) string {
	matches := titleRe.FindStringSubmatch(htmlStr)
	if len(matches) > 1 {
		return strings.TrimSpace(html.UnescapeString(matches[1]))
	}
	return ""
}

func extractDescription(htmlStr string) string {
	matches := metaRe.FindAllStringSubmatch(htmlStr, -1)
	for _, m := range matches {
		attrs := strings.ToLower(m[1])
		if strings.Contains(attrs, `name="description"`) || strings.Contains(attrs, `name='description'`) {
			if cm := contentRe.FindStringSubmatch(m[1]); len(cm) > 1 {
				return strings.TrimSpace(html.UnescapeString(cm[1]))
			}
		}
	}
	return ""
}

func main() {
	log.Println("Starting server on :8080")
	if err := fasthttp.ListenAndServe(":8080", FetchURLPreview); err != nil {
		log.Fatalf("Error in ListenAndServe: %v", err)
	}
}

