// extractPreviewData parses HTML body to find <title> and <meta name="description" content="...">
func extractPreviewData(body []byte) (title, description string) {
	z := html.NewTokenizer(bytes.NewReader(body))
	for {
		tt := z.Next()
		if tt == html.ErrorToken {
			break
		}

		if tt == html.StartTagToken || tt == html.SelfClosingTagToken {
			tn, _ := z.TagName()
			tagName := strings.ToLower(string(tn))

			if tagName == "title" {
				// Consume tokens until we hit text or the closing tag
				for {
					t := z.Next()
					if t == html.TextToken {
						title = strings.TrimSpace(string(z.Text()))
					} else if t == html.EndTagToken || t == html.ErrorToken {
						break
					}
				}
			} else if tagName == "meta" {
				var isDesc bool
				var content string
				// Iterate over all attributes of the meta tag
				for {
					key, val, more := z.TagAttr()
					k := strings.ToLower(string(key))
					v := strings.ToLower(string(val))
					if k == "name" && v == "description" {
						isDesc = true
					}
					if k == "content" {
						content = string(val)
					}
					if !more {
						break
					}
				}
				if isDesc && content != "" {
					description = strings.TrimSpace(content)
				}
			}
		}

		// Early exit if both fields are found
		if title != "" && description != "" {
			break
		}
	}
	return
}

// FetchURLPreview handles POST requests, fetches the URL, extracts preview data, and returns JSON
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString(`{"error":"method not allowed"}`)
		return
	}

	var reqBody URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &reqBody); err != nil || reqBody.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"invalid request body or missing url"}`)
		return
	}

	req := fasthttp.AcquireRequest()
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req)
	defer fasthttp.ReleaseResponse(resp)

	req.SetRequestURI(reqBody.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	// Use DoRedirects as required
	if err := httpClient.DoRedirects(req, resp, 5); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error":"failed to fetch url"}`)
		return
	}

