// safeDial resolves the hostname and verifies that the IP address is public.
// This effectively mitigates SSRF attacks, including DNS rebinding and redirect-based bypasses.
func safeDial(addr string) (net.Conn, error) {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		host = addr
	}

	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, fmt.Errorf("DNS lookup failed: %w", err)
	}

	if len(ips) == 0 {
		return nil, fmt.Errorf("no IP addresses found for host %s", host)
	}

	// Block request if ANY resolved IP is internal/private to prevent DNS rebinding attacks
	for _, ip := range ips {
		if isInternalIP(ip) {
			return nil, fmt.Errorf("access to internal or private IP addresses is not allowed")
		}
	}

	dialer := &net.Dialer{Timeout: 5 * time.Second}
	return dialer.Dial("tcp", addr)
}

// isInternalIP checks if an IP address is loopback, link-local, private, or unspecified.
func isInternalIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
		return true
	}
	// IsPrivate() covers RFC 1918 (IPv4) and RFC 4193 (IPv6 ULA)
	if ip.IsPrivate() {
		return true
	}
	return false
}

