package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"log"
	"net/url"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
	"golang.org/x/net/html/atom"
)

// HTTP client configured with DualStack dialer as required
var httpClient = &fasthttp.Client{
	Dial: fasthttp.DialDualStack,
}

type URLRequest struct {
	URL string `json:"url"`
}

type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

type ErrorResponse struct {
	Error string `json:"error"`
}

func sendJSON(ctx *fasthttp.RequestCtx, statusCode int, v interface{}) {
	ctx.SetStatusCode(statusCode)
	ctx.SetContentType("application/json")
	data, _ := json.Marshal(v)
	ctx.Write(data)
}

// getText recursively extracts and concatenates text nodes from an HTML node
func getText(n *html.Node) string {
	var buf strings.Builder
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.TextNode {
			buf.WriteString(n.Data)
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(n)
	return strings.TrimSpace(buf.String())
}

// extractTitleAndDescription traverses the HTML tree to find <title> and <meta name="description">
func extractTitleAndDescription(doc *html.Node) (string, string) {
	var title, description string
	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.DataAtom == atom.Title && title == "" {
				title = getText(n)
			}
			if n.DataAtom == atom.Meta && description == "" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" {
					description = strings.TrimSpace(content)
				}
			}
		}
		// Continue traversal only if we haven't found both elements yet
		if title == "" || description == "" {
			for c := n.FirstChild; c != nil; c = c.NextSibling {
				f(c)
			}
		}
	}
	f(doc)
	return title, description
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		sendJSON(ctx, fasthttp.StatusMethodNotAllowed, ErrorResponse{Error: "method not allowed"})
		return
	}

	var req URLRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		sendJSON(ctx, fasthttp.StatusBadRequest, ErrorResponse{Error: "invalid json"})
		return
	}

	if req.URL == "" {
		sendJSON(ctx, fasthttp.StatusBadRequest, ErrorResponse{Error: "url is required"})
		return
	}

	if _, err := url.ParseRequestURI(req.URL); err != nil {
		sendJSON(ctx, fasthttp.StatusBadRequest, ErrorResponse{Error: "invalid url format"})
		return
	}

	fastReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(fastReq)
	fastReq.SetRequestURI(req.URL)
	fastReq.Header.SetMethod("GET")

	fastResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(fastResp)

	// Use DoRedirects as explicitly required
	if err := httpClient.DoRedirects(fastReq, fastResp, 5); err != nil {
		sendJSON(ctx, fasthttp.StatusBadGateway, ErrorResponse{Error: fmt.Sprintf("failed to fetch url: %v", err)})
		return
	}

	if fastResp.StatusCode() != fasthttp.StatusOK {
		sendJSON(ctx, fasthttp.StatusBadGateway, ErrorResponse{Error: fmt.Sprintf("unexpected status code: %d", fastResp.StatusCode())})
		return
	}

	doc, err := html.Parse(bytes.NewReader(fastResp.Body()))
	if err != nil {
		sendJSON(ctx, fasthttp.StatusUnprocessableEntity, ErrorResponse{Error: "failed to parse html"})
		return
	}

	title, desc := extractTitleAndDescription(doc)
	sendJSON(ctx, fasthttp.StatusOK, PreviewResponse{Title: title, Description: desc})
}

func main() {
	router := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("not found", fasthttp.StatusNotFound)
		}
	}

	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", router); err != nil {
		log.Fatalf("Failed to start server: %v", err)
	}
}

